def get_parameters(
    vault: SmartContractVault, param_fetcher_id: str = WELCOME_BONUS_POF_ID
) -> dict[str, datetime | Decimal | str | None]:
    """Get welcome bonus parameters from vault fetcher.

    Args:
        vault (SmartContractVault): Vault object.
        param_fetcher_id (str, optional): Welcome bonus parameter fetcher id. Defaults to
            WELCOME_BONUS_POF_ID.

    Returns:
        dict[str, datetime | Decimal | str | None]: Welcome bonus parameters
    """
    return vault.get_parameters_observation(fetcher_id=param_fetcher_id).parameters


def _append_to_state(
    state: state_utils.SmartContractState,
    balance_fetcher_id: str = common_fetchers.ALL_BALANCES_ET_BOF_ID,
    param_fetcher_id: str = WELCOME_BONUS_POF_ID,
) -> state_utils.SmartContractState:
    """Updates the contract state with balances and welcome bonus parameters."""
    return state_utils.append_to_state(
        state=state,
        parameters=get_parameters(state.vault, param_fetcher_id),
        balances=state.vault.get_balances_observation(fetcher_id=balance_fetcher_id).balances,
    )


def _get_balance_at_address(balances: Mapping, address: str, denomination: str) -> Decimal:
    """Gets the net balance at a specific address."""
    return balances[(address, DEFAULT_ASSET, denomination, Phase.COMMITTED)].net


def track_and_award_welcome_bonus(
    state: state_utils.SmartContractState,
    transaction_amount: Decimal,
    transaction_type: str,
    account_type: str = "",
    fetchers_config: WelcomeBonusFetchersConfig = DEFAULT_WELCOME_BONUS_FETCHERS_CONFIG,
) -> list[CustomInstruction]:
    """Tracks spending toward the welcome bonus threshold and awards bonus points.

    Awards bonus points when the threshold is met within the qualifying period.
    Only purchase transactions count (not cash advances or fees).
    The bonus is a one-time award - once WELCOME_BONUS_SPEND_TRACKER reaches
    the threshold, no further tracking occurs.

    Args:
        state: The current state of the smart contract.
        transaction_amount: The purchase transaction amount (positive).
        transaction_type: Type from instruction_details["transaction_type"].
        account_type: The account type for GL impact details.
        fetchers_config: Configuration for the fetchers.

    Returns:
        List of custom instructions for spend tracking and bonus award.
    """
    # Only purchases count toward welcome bonus
    if transaction_type != "PURCHASE":
        return []

    if transaction_amount == 0:
        return []

    state = _append_to_state(
        state=state,
        param_fetcher_id=fetchers_config.param_fetcher_id,
    )

    rejection = state_utils.check_parameters_exist(
        state=state,
        param_ids={
            fetchers_config.denomination_param_id,
            WELCOME_BONUS_THRESHOLD_PARAM.id,
            WELCOME_BONUS_POINTS_PARAM.id,
            WELCOME_BONUS_PERIOD_DAYS_PARAM.id,
        },
    )
    assert rejection is None, rejection

    denomination: str = str(state.parameters[fetchers_config.denomination_param_id])
    threshold: Decimal = state.parameters[WELCOME_BONUS_THRESHOLD_PARAM.id]  # type: ignore
    bonus_points: Decimal = state.parameters[WELCOME_BONUS_POINTS_PARAM.id]  # type: ignore
    period_days: int = int(state.parameters[WELCOME_BONUS_PERIOD_DAYS_PARAM.id])  # type: ignore

    # Check if we're within the qualifying period
    activation_datetime = state.vault.get_account_creation_datetime()
    days_since_opening = (state.effective_datetime - activation_datetime).days

    if days_since_opening > period_days:
        return []

    # Get current cumulative spend toward bonus
    current_spend = _get_balance_at_address(
        state.balances, apex_addresses.WELCOME_BONUS_SPEND_TRACKER, denomination
    )

    # Handle refund (negative transaction_amount)
    if transaction_amount < 0:
        refund_amount = abs(transaction_amount)
        # Cap refund decrement at current spend tracker to prevent negative tracker
        decrement = min(refund_amount, max(current_spend, Decimal(0)))
        if decrement <= 0:
            return []
        # Reverse the spend tracking: credit WELCOME_BONUS_SPEND_TRACKER, debit DEFAULT
        return [
            CustomInstruction(
                postings=posting_utils.create_postings(
                    amount=decrement,
                    debit_account=state.vault.account_id,
                    debit_address=DEFAULT_ADDRESS,
                    credit_account=state.vault.account_id,
                    credit_address=apex_addresses.WELCOME_BONUS_SPEND_TRACKER,
                    denomination=denomination,
                ),
                instruction_details=posting_utils.standard_instruction_details(
                    description=f"Welcome bonus spend reversal: {decrement}",
                    event_type=WELCOME_BONUS_EVENT,
                    gl_impacted=False,
                    account_type=account_type,
                ),
                override_all_restrictions=True,
            )
        ]

    # Positive transaction: track spend toward threshold

    # If threshold already met, no more tracking needed
    if current_spend >= threshold:
        return []

    instructions: list[CustomInstruction] = []

    # Track the spend
    instructions.append(
        CustomInstruction(
            postings=posting_utils.create_postings(
                amount=transaction_amount,
                debit_account=state.vault.account_id,
                debit_address=apex_addresses.WELCOME_BONUS_SPEND_TRACKER,
                credit_account=state.vault.account_id,
                credit_address=DEFAULT_ADDRESS,
                denomination=denomination,
            ),
            instruction_details=posting_utils.standard_instruction_details(
                description=f"Welcome bonus spend tracking: {transaction_amount}",
                event_type=WELCOME_BONUS_EVENT,
                gl_impacted=False,
                account_type=account_type,
            ),
            override_all_restrictions=True,
        )
    )

    # Check if threshold is now met (with this transaction)
    new_spend = current_spend + transaction_amount
    if new_spend >= threshold:
        # Award bonus points to REWARDS_POINTS
        instructions.append(
            CustomInstruction(
                postings=posting_utils.create_postings(
                    amount=bonus_points,
                    debit_account=state.vault.account_id,
                    debit_address=apex_addresses.REWARDS_POINTS,
                    credit_account=state.vault.account_id,
                    credit_address=DEFAULT_ADDRESS,
                    denomination=denomination,
                ),
                instruction_details=posting_utils.standard_instruction_details(
                    description=(
                        f"Welcome bonus awarded: {bonus_points} points. "
                        f"Spend threshold of {threshold} met."
                    ),
                    event_type=WELCOME_BONUS_EVENT,
                    gl_impacted=False,
                    account_type=account_type,
                ),
                override_all_restrictions=True,
            )
        )

    return instructions
